    try a.vinst(.vaddps, .{ v.zmm(1), v.zmm(2), v.zmm(3) }, .{ .rc = .rn });
    fails += check(&cb, &.{ 0x62, 0xf1, 0x6c, 0x18, 0x58, 0xcb }, "vaddps zmm1, zmm2, zmm3, {rn-sae}");
    try a.vinst(.vaddps, .{ v.zmm(1), v.zmm(2), v.zmm(3) }, .{ .rc = .rd });
    fails += check(&cb, &.{ 0x62, 0xf1, 0x6c, 0x38, 0x58, 0xcb }, "vaddps zmm1, zmm2, zmm3, {rd-sae}");
    try a.vinst(.vaddps, .{ v.zmm(1), v.zmm(2), v.zmm(3) }, .{ .rc = .ru });
    fails += check(&cb, &.{ 0x62, 0xf1, 0x6c, 0x58, 0x58, 0xcb }, "vaddps zmm1, zmm2, zmm3, {ru-sae}");
    try a.vinst(.vaddps, .{ v.zmm(1), v.zmm(2), v.zmm(3) }, .{ .rc = .rz });
    fails += check(&cb, &.{ 0x62, 0xf1, 0x6c, 0x78, 0x58, 0xcb }, "vaddps zmm1, zmm2, zmm3, {rz-sae}");
    try a.vinst(.vmaxps, .{ v.zmm(1), v.zmm(2), v.zmm(3) }, .{ .sae = true });
    fails += check(&cb, &.{ 0x62, 0xf1, 0x6c, 0x18, 0x5f, 0xcb }, "vmaxps zmm1, zmm2, zmm3, {sae}");
    try a.vinst(.vpcmpeqd, .{ v.k(1), v.zmm(2), v.zmm(30) }, .{});
    fails += check(&cb, &.{ 0x62, 0x91, 0x6d, 0x48, 0x76, 0xce }, "vpcmpeqd k1, zmm2, zmm30");
    try a.vinst(.vcmpps, .{ v.k(3), v.zmm(2), v.zmm(3), 1 }, .{});
    fails += check(&cb, &.{ 0x62, 0xf1, 0x6c, 0x48, 0xc2, 0xdb, 0x01 }, "vcmpps k3, zmm2, zmm3, 1");
    try a.vinst(.kandw, .{ v.k(1), v.k(2), v.k(3) }, .{});
    fails += check(&cb, &.{ 0xc5, 0xec, 0x41, 0xcb }, "kandw k1, k2, k3");
    try a.vinst(.kmovw, .{ v.k(1), gp.r32(.rax) }, .{});
    fails += check(&cb, &.{ 0xc5, 0xf8, 0x92, 0xc8 }, "kmovw k1, eax");
    try a.vinst(.vpermd, .{ v.zmm(1), v.zmm(2), v.zmm(3) }, .{});
    fails += check(&cb, &.{ 0x62, 0xf2, 0x6d, 0x48, 0x36, 0xcb }, "vpermd zmm1, zmm2, zmm3");
    try a.vinst(.vpternlogd, .{ v.zmm(1), v.zmm(2), v.zmm(3), 0xca }, .{});
    fails += check(&cb, &.{ 0x62, 0xf3, 0x6d, 0x48, 0x25, 0xcb, 0xca }, "vpternlogd zmm1, zmm2, zmm3, 0xca");
    try a.vinst(.vcvtdq2ps, .{ v.zmm(1), v.zmm(25) }, .{});
    fails += check(&cb, &.{ 0x62, 0x91, 0x7c, 0x48, 0x5b, 0xc9 }, "vcvtdq2ps zmm1, zmm25");
    try a.vinst(.vextracti64x4, .{ v.ymm(1), v.zmm(2), 1 }, .{});
    fails += check(&cb, &.{ 0x62, 0xf3, 0xfd, 0x48, 0x3b, 0xd1, 0x01 }, "vextracti64x4 ymm1, zmm2, 1");
    try a.vinst(.vbroadcastss, .{ v.zmm(9), v.xmm(1) }, .{});
    fails += check(&cb, &.{ 0x62, 0x72, 0x7d, 0x48, 0x18, 0xc9 }, "vbroadcastss zmm9, xmm1");
    try a.vinst(.vpbroadcastd, .{ v.zmm(9), gp.r32(.rcx) }, .{});
    fails += check(&cb, &.{ 0x62, 0x72, 0x7d, 0x48, 0x7c, 0xc9 }, "vpbroadcastd zmm9, ecx");
    try a.vinst(.vmovdqu32, .{ v.zmm(1), v.mem(x.ptr(.rsi, 128), 64) }, .{ .k = 1, .z = true });
    fails += check(&cb, &.{ 0x62, 0xf1, 0x7e, 0xc9, 0x6f, 0x4e, 0x02 }, "vmovdqu32 zmm1 {k1} {z}, zmmword ptr [rsi+128]");
    try a.vinst(.vmovdqu64, .{ v.mem(x.ptr(.rsi, -64), 64), v.zmm(31) }, .{ .k = 4 });
    fails += check(&cb, &.{ 0x62, 0x61, 0xfe, 0x4c, 0x7f, 0x7e, 0xff }, "vmovdqu64 zmmword ptr [rsi-64] {k4}, zmm31");
    try a.vinst(.vgatherdps, .{ v.zmm(1), v.vsib(.rax, v.zmm(2), .x4, 0, 4) }, .{ .k = 1 });
    fails += check(&cb, &.{ 0x62, 0xf2, 0x7d, 0x49, 0x92, 0x0c, 0x90 }, "vgatherdps zmm1 {k1}, dword ptr [rax+4*zmm2]");
    try a.vinst(.vscatterdps, .{ v.vsib(.rax, v.zmm(18), .x4, 64, 4), v.zmm(1) }, .{ .k = 2 });
    fails += check(&cb, &.{ 0x62, 0xf2, 0x7d, 0x42, 0xa2, 0x4c, 0x90, 0x10 }, "vscatterdps dword ptr [rax+4*zmm18+64] {k2}, zmm1");
    try std.testing.expectEqual(@as(u32, 0), fails);
}

test "x86_64 AVX-512 via vinst: validation and hooks" {
    if (!opts.x86_64) return error.SkipZigTest;
    var cb = CodeBuffer.init(std.testing.allocator);
    defer cb.deinit();
    // xmm16+ do not exist in legacy SSE / VEX-only forms.
    try std.testing.expect(std.meta.isError(x.Assembler.init(&cb).vinst(.addps, .{ v.xmm(16), v.xmm(1) }, .{})));
    var h: x.CountingHooks = .{};
    const ah = x.AssemblerT(.{ .Hooks = x.CountingHooks }).initHooks(&cb, &h);
    try ah.vinst(.vaddps, .{ v.zmm(1), v.zmm(2), v.zmm(3) }, .{});
    try std.testing.expectEqual(@as(usize, 1), h.instructions);
    try std.testing.expectEqual(@as(usize, 6), h.bytes);
}
